const code=s.slice(s.indexOf('export const githubRetry'),s.indexOf('export function slugify'))+s.slice(s.indexOf('export async function pushExistingBranch('),s.indexOf('export async function createPullRequest('));
let owned=true,pushes=0,guards=0;
