const js=new Bun.Transpiler({loader:'ts'}).transformSync(code).replaceAll('export ','');
const api=new Function('CommandError','cacheGit','sh','worktreeGit','withTransportRepo','BRANCH_PUSH',js+';return {pushExistingBranch,githubRetry}')(CommandError,git,git,async()=>({stdout:'head',exitCode:0}),async(a,b,c,f)=>f('transport'),['git','push']);
api.githubRetry.baseDelayMs=1;
await api.pushExistingBranch({kind:'github',url:'fake'},'cwd','topic','base',undefined,undefined,'head',()=>{guards++;if(!owned)throw Error('lost');});
console.log({guards,pushes,owned});
strictEqual(pushes,1);
